SRC={'01':'A','03':'B','04':'C','05':'D','06':'D2'}
for k,v in V.items():
    if not v: continue
    b=v['b'];d=json.load(open(f'/home/claude/voice/src_{b}.json'));tl=json.load(open(f'/home/claude/render/{b}_tl.json'))
    W={s['key']:s['w'] for s in tl['segs'] if 'key' in s};SL=d['SL']
    def start(code):
        if code=='END': return None
        i=[s['name'].split(' ')[0] for s in SL].index(code);t0=SL[i]['t'];t1=SL[i+1]['t'] if i+1<len(SL) else 1e9
        return min(W[f"{l['id']}#{l['ix']}"] for l in d['L'] if t0<=l['t']<t1 and f"{l['id']}#{l['ix']}" in W)
    import subprocess
    src=f'/home/claude/out/khutwa_hist_L1_{b}_voice.mp4'
    dur=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0',src]))
    secs=[{'at':0 if i==0 else start(c),'title':t} for i,(c,t) in enumerate(v['st'])]
    pz=[];prev=0
    for c,h,pts in v['pz']:
        a=start(c);a=dur-0.05 if a is None else a
        back=max([s['at'] for s in secs if s['at']<a-1] or [0])
        pz.append({'at':a,'back':back,'head':h,'points':pts,'dur':15})
    cfg={'src':src,'out':f'/home/claude/montage/d1_{k}_final.mp4','lesson':L,'part':f'{int(k)}/6','sections':secs,'pauses':pz}
    json.dump(cfg,open(f'cfg/d1_{k}.json','w'),ensure_ascii=False,indent=1);print(k,[round(s['at']) for s in secs],[round(p['at']) for p in pz],round(dur))
